def head(title, description, prefix):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>{escape(title)}</title><meta name="description" content="{escape(description, quote=True)}"><link rel="icon" type="image/svg+xml" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>'''

def header(prefix):
    home = prefix + 'index.html'
    return f'''<header><div class="wrap"><a class="brand" href="{home}" aria-label="Merci homepage">Merci<span>.</span></a><nav aria-label="Main navigation"><a href="{home}#work">Work</a><a href="{home}#about">About</a><a href="{home}#contact">Contact</a></nav></div></header>'''

def footer(prefix):
    return f'''<footer><div class="wrap"><span>Merci · Geometry, perception & simulation</span><div class="footer-links"><a href="https://github.com/hyandnn">GitHub</a><a href="mailto:haoling.yang@rwth-aachen.de">Email</a></div></div></footer></body></html>'''

def card(p):
    if p['slug'] in ('stereo','lidar'):
        visual = f'<canvas data-scene="{p["slug"]}" data-preview="true" role="img" aria-label="Synthetic top-view {p["name"]} illustration"></canvas>'
    else:
        visual = f'<img src="assets/{p["slug"]}-preview.png" width="1080" height="380" loading="lazy" alt="Synthetic {p["name"]} conceptual illustration">'
    return f'''<a class="project-card {p['theme']}" href="projects/{p['slug']}.html"><div class="card-view">{visual}</div><div class="card-copy"><div class="card-heading"><span class="index">{p['number']}</span><h3>{p['name']}</h3></div><p>{p['summary']}</p><div class="card-foot"><span class="mono">{p['topic']}</span><span>Read case study</span></div></div></a>'''

home = head('Merci — Perception Algorithm Engineer', 'Perception engineering in consumer robotics. Selected work in stereo, LiDAR, collision detection and visual motion analysis.', '') + header('') + '''<main id="main">
<section class="hero" aria-labelledby="hero-title"><div><div class="eyebrow">Perception Algorithm Engineer</div><h1 id="hero-title">From observations<br>to <span>geometry.</span></h1><p class="intro">I’m Merci. I build perception software that turns imperfect sensor observations into useful geometry for robots.</p><div class="hero-actions"><a class="text-link" href="#work">Explore selected work</a><a class="text-link" href="https://github.com/hyandnn">GitHub profile</a></div></div><div class="hero-visual"><div class="visual-top mono"><span>GEOMETRY / TEMPORAL CONTEXT</span><span>SYNTHETIC</span></div><canvas data-scene="hero" role="img" aria-label="Isometric conceptual visualization of observed points and scene geometry"></canvas><div class="visual-bottom"><span>Observations → representation</span><span>Conceptual illustration</span></div></div></section>
<div class="principles"><div><b>Perception in consumer robotics</b><p>Stereo-led and LiDAR-led systems</p></div><div><b>Geometry with sensor context</b><p>Supporting IMU and odometry information</p></div><div><b>Engineering beyond the model</b><p>Integration, deployment and runtime efficiency</p></div></div>
<section id="work" aria-labelledby="work-title"><div class="section-top"><div><div class="eyebrow">Selected work / 01—04</div><h2 id="work-title">Four problems.<br>Concrete contributions.</h2></div><p>What I worked on, what changed, and the engineering decisions behind it.</p></div><div class="work-grid">''' + ''.join(card(p) for p in PROJECTS) + '''</div><p class="notice">Visuals are independently created conceptual illustrations using synthetic data. They do not show product recordings, internal implementations or measured research results.</p></section>
<section class="about" id="about" aria-labelledby="about-title"><div><div class="eyebrow">About / Merci</div><h2 id="about-title">Geometry.<br>Context.<br>Implementation.</h2></div><div class="about-text"><p>I work as a Perception Algorithm Engineer in consumer robotics. My focus spans geometric reasoning, model post-processing, temporal consistency and efficient C++ implementation.</p><p>I hold an M.Sc. in <b>Robotic Systems Engineering</b> from <b>RWTH Aachen University</b>. My earlier work includes physics-simulation integration and vision-based movement analysis.</p><div class="toolkit"><div><b>Implementation</b><p>C++ · Python · CMake<br>Profiling & runtime optimization</p></div><div><b>Perception</b><p>OpenCV · Point clouds<br>Geometry, semantics & tracking</p></div><div><b>Simulation</b><p>Collision detection<br>Spatial hierarchies & engine integration</p></div></div><p style="font-size:.9rem;margin-top:24px">Additional research: a small neural-network surrogate for manufacturing simulation, paired with an interactive interface.</p></div></section>
<section class="contact" id="contact" aria-labelledby="contact-title"><div><div class="eyebrow">Contact</div><h2 id="contact-title">Let’s talk engineering.</h2><p>Perception, geometry and systems that work in practice.</p></div><a class="text-link" href="mailto:haoling.yang@rwth-aachen.de">haoling.yang@rwth-aachen.de</a></section></main>''' + footer('')
(ROOT / 'index.html').write_text(home)

def demo(p):
    slug = p['slug']
    if slug in ('stereo','lidar'):
        labels = [('points','Observations'),('geometry','Geometry')] if slug == 'stereo' else [('points','Returns'),('rays','Sampled rays'),('tracks','Track')]
        controls = ''.join(f'<label><input type="checkbox" data-layer="{key}" checked>{label}</label>' for key,label in labels)
        caption = 'Top view. Depth-valid samples form surfaces with gaps and occlusion; the cyan thin-obstacle representation is illustrative inferred geometry.' if slug == 'stereo' else 'Top view. Angular samples stop at the first surface. A moving target passes behind a static obstacle; the dotted track segment illustrates continuity during occlusion.'
        return f'''<div class="demo" data-demo="{slug}"><div class="demo-head"><span>Explore the concept · {p['name']}</span><span>Independent synthetic demonstration</span></div><canvas data-scene="{slug}" role="img" aria-label="{escape(caption)}"></canvas><div class="demo-controls"><button type="button" data-play aria-pressed="false">Pause</button><label class="timeline"><span class="sr-label" hidden>Time</span><input type="range" min="0" max="1000" value="0" data-time aria-label="Demonstration time"><output data-time-label>0.0 s</output></label><div class="layers" aria-label="Visualization layers">{controls}</div></div><p class="demo-caption">{caption}</p></div>'''
    return f'''<div class="demo" data-media-demo><div class="demo-head"><span>Conceptual sequence · {p['name']}</span><span>Independent synthetic illustration</span></div><div class="media-scroll"><img class="wide-image" src="../assets/{slug}-preview.png" data-static="../assets/{slug}-preview.png" data-motion="../assets/{slug}.gif" width="1080" height="380" alt="{'Broadphase candidates, BVH hierarchy and convex geometry query.' if slug=='collision' else 'Pose observations, video-frame correspondence with a wall template, and an illustrative movement trace.'}"></div><div class="media-row"><button class="media-toggle" type="button" aria-pressed="false">Play illustration</button><small>Static by default. On small screens, scroll the illustration horizontally.</small></div></div>'''

for i,p in enumerate(PROJECTS):
    body = head(p['name']+' — Merci', p['summary'], '../') + header('../')
    body += f'''<main id="main" class="{p['theme']}"><a class="back" href="../index.html#work">All selected work</a><section class="case-head"><div class="eyebrow">{p['number']} / {p['name']}</div><h1>{p['title']}</h1><p class="lead">{p['lead']}</p><div class="case-meta"><div><span class="label mono">MY ROLE</span><p>{p['role']}</p></div><div><span class="label mono">CONTEXT</span><p>{p['context']}</p></div></div></section>'''
    body += demo(p)
    for k,(label,title,content) in enumerate(p['sections']):
        body += f'<section class="story"><div class="story-index mono">0{k+1} / {label}</div><div class="story-body"><h2>{title}</h2>{content}</div></section>'
    prev,nxt = PROJECTS[(i-1)%4], PROJECTS[(i+1)%4]
    body += f'''<div class="boundary">All demonstrations use synthetic data. Project descriptions are limited to publicly shareable responsibilities and conceptual explanations.</div><div class="case-nav"><div><small>Previous case</small><a href="{prev['slug']}.html">{prev['name']}</a></div><div><small>Next case</small><a href="{nxt['slug']}.html">{nxt['name']}</a></div></div></main>''' + footer('../')
    (ROOT/'projects'/f'{p["slug"]}.html').write_text(body)

(ROOT/'404.html').write_text(head('Page not found — Merci', 'Return to Merci’s portfolio.', '')+header('')+'<main id="main" class="empty-page"><div class="eyebrow">404</div><h1>Page not found.</h1><p class="muted" style="margin-top:24px">This address does not point to a case study.</p><a class="text-link" href="index.html">Return to the portfolio</a></main>'+footer(''))
print('Built homepage, 4 case studies and 404 page.')
